const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const swannanoaRiver = ee.Geometry.Point([-82.44, 35.59]); // Representative point on Swannanoa River, near Asheville, NC
  const scale = 10; // Sentinel-2 resolution for visible bands

  const date1_start = '2024-10-02';
  const date1_end = '2024-10-03'; // One day window for target date
  const date2_start = '2024-08-30';
  const date2_end = '2024-08-31'; // One day window for target date

  // Sentinel-2 cloud masking function based on SCL band
  function maskS2clouds(image) {
    const qa = image.select('SCL');
    // Clouds, cloud shadows, and cirrus are values 3, 8, 9, 10, 11
    // Pixels with value 3 (cloud shadow), 8 (medium probability cloud), 9 (high probability cloud), 10 (cirrus), 11 (snow/ice)
    const cloudMask = qa.eq(3).or(qa.gte(8));
    return image.updateMask(cloudMask.not());
  }

  // Function to get image, mask, and calculate "brownness"
  async function getImageAndBrownness(startDate, endDate, name) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(swannanoaRiver)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Pre-filter by metadata cloud cover
      .map(maskS2clouds)
      .select(['B4', 'B3']); // Red and Green bands for "brownness"

    let collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`${name} Images: 0`);
      return { value: null, pixels: 0, msg: `C1: No images found for ${startDate}` };
    }

    // Get the least cloudy image
    let image = await collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    let cloudPercentage = image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();

    // Calculate mean reflectance of Red and Green bands (proxy for brownness)
    let brownness = image.expression('(B4 + B3) / 2', {
      'B4': image.select('B4'),
      'B3': image.select('B3')
    });

    let stats = await brownness.reduceRegion({
      reducer: ee.Reducer.mean().setOutputs(['mean']),
      geometry: swannanoaRiver,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    let value = stats['mean'];

    // Validate pixel count
    let pixelCount = await brownness.reduceRegion({
      reducer: ee.Reducer.count().setOutputs(['count']),
      geometry: swannanoaRiver,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    let validPixels = pixelCount['count'];

    if (validPixels === 0) {
      console.log(`${name} Images: ${collectionSize} (Cloud: ${cloudPercentage.toFixed(1)}%)`);
      return { value: null, pixels: 0, msg: `C2: No valid pixels remaining for ${startDate} after masking.` };
    }

    console.log(`${name} Images: ${collectionSize} (Cloud: ${cloudPercentage.toFixed(1)}%, Val: ${validPixels})`);
    return { value: value, pixels: validPixels };
  }

  console.log("Fetching data for October 2, 2024:");
  const data1 = await getImageAndBrownness(date1_start, date1_end, 'Oct 2');

  console.log("Fetching data for August 30, 2024:");
  const data2 = await getImageAndBrownness(date2_start, date2_end, 'Aug 30');

  // 5. Validation & Final Answer
  if (data1.value === null) {
    console.log(data1.msg);
    if (data1.msg.startsWith('C1')) {
      console.log('C1');
    } else {
      console.log('C2');
    }
    return;
  }
  if (data2.value === null) {
    console.log(data2.msg);
    if (data2.msg.startsWith('C1')) {
      console.log('C1');
    } else {
      console.log('C2');
    }
    return;
  }

  if (data1.value === undefined || data1.value === null || isNaN(data1.value) ||
      data2.value === undefined || data2.value === null || isNaN(data2.value)) {
    console.log("C3: Calculation resulted in invalid value.");
    return;
  }

  console.log(`Mean (B4+B3)/2 for Oct 2, 2024: ${data1.value.toFixed(2)}`);
  console.log(`Mean (B4+B3)/2 for Aug 30, 2024: ${data2.value.toFixed(2)}`);

  // "Browner" implies higher reflectance in Red/Green bands
  if (data1.value > data2.value) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
